      ctx.fillStyle = a.q > 0 ? 'rgba(255,90,78,0.95)' : 'rgba(77,141,255,0.95)';
      ctx.beginPath(); ctx.arc(bx, by, 7.5, 0, Math.PI * 2); ctx.fill();
