    kv.push(['Mass', '9.109×10⁻³¹ kg (1/1836 of a proton)'], ['Kinetic energy', fmtE(ke)], ['Speed', fmtSpeed(speed)]);
    kv.push(...gyroRows(p.q, PHYS.ME, p.rad ? 1 + p.KE / (PHYS.ME * PHYS.AMU_MEV * 1e6) : 1, speed, p.x, p.y, p));
