  const m = (R.measure || []).filter(p => !p.dead); if (m.length < 2) return '';
  let t = `${fmtA(measureDist(m[0], m[1]))}`;
  if (m.length >= 3) t += ` and ${fmtA(measureDist(m[1], m[2]))}; angle ${measureAngle(m[0], m[1], m[2]).toFixed(1)}°`;
